import java.util.*;
public class TestMain{static final class Repo implements StudentRepository{Set<String>ids=new HashSet<>(Set.of("old"));Set<String>emails=new HashSet<>(Set.of("old@x"));int calls;List<Student>saved;public boolean existsId(String x){return ids.contains(x);}public boolean existsEmail(String x){return emails.contains(x);}public void saveAll(List<Student>x){calls++;saved=x;}}
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}public static void main(String[]a){Repo r=new Repo();StudentImporter i=new StudentImporter(r);try{i.importAll(List.of(new Student(" a ","A@X "),new Student("a","b@x"),new Student("old","old@x")));throw new AssertionError();}catch(BatchValidationException e){check(e.errors().equals(List.of("row 2: duplicate id a","row 3: existing id old","row 3: existing email old@x")),"errors "+e.errors());}check(r.calls==0,"atomic");i.importAll(List.of(new Student(" n1 "," N1@X "),new Student("n2","n2@x")));check(r.calls==1,"one saveAll");check(r.saved.equals(List.of(new Student("n1","n1@x"),new Student("n2","n2@x"))),"normalized");try{r.saved.add(new Student("x","x"));throw new AssertionError();}catch(UnsupportedOperationException e){}System.out.println("OK");}}
